 // A standalone trigger already toggles through its native click, which Enter and Space fire.\n    if ((event.key === 'Enter' || event.key === ' ') && event.target === this.triggerAnchor()) {\n      return;\n    }\n\n    if (this.open()) {\n      this.onKeydownWhileOpen(event);\n      return;\n    }\n\n    switch (event.key) {\n      case 'ArrowDown':\n        event.preventDefault();\n        this.openPanel();\n        this.highlightEdge('first');\n        break;\n      case 'ArrowUp':\n        event.preventDefault();\n        this.openPanel();\n        this.highlightEdge('last');\n        break;\n      case 'Enter':\n        event.preventDefault();\n        this.openPanel();\n        break;\n      case 'Escape':\n        if (this.hasValue()) {\n          event.preventDefault();\n          this.clear();\n        }\n        break;\n    }\n  }\n\n  private onKeydownWhileOpen(event: KeyboardEvent): void {\n    switch (event.key) {\n      case 'ArrowDown':\n        event.preventDefault();\n        this.moveHighlight(1);\n        break;\n      case 'ArrowUp':\n        event.preventDefault();\n        this.moveHighlight(-1);\n        break;\n      case 'Home':\n        event.preventDefault();\n        this.highlightEdge('first');\n        break;\n      case 'End':\n        event.preventDefault();\n        this.highlightEdge('last');\n        break;\n      case 'Enter': {\n        event.preventDefault();\n        const item = this.highlightedItem();\n        if (item) {\n          this.selectItem(item);\n        }\n        break;\n      }\n      case 'Escape':\n        event.preventDefault();\n        this.closePanel();\n        this.focusInput();\n        break;\n      case 'Tab':\n        this.closePanel();\n        break;\n    }\n  }\n\n  private moveHighlight(direction: 1 | -1): void {\n    const items = this.selectableItems();\n    if (items.length === 0) {\n      return;\n    }\n\n    const current = this.highlightedItem();\n    const currentIndex = current ? items.